function mergeORSet(localAdds, remoteAdds, localRemoves, remoteRemoves) {
  const adds = new Set([...localAdds, ...remoteAdds]);
  const removes = new Set([...localRemoves, ...remoteRemoves]);
  return Array.from(adds).filter(x => !removes.has(x));
}
